// dyna:semver against node-semver, the reference implementation whose range
// grammar and prerelease rule the contract follows
// (tests/corpus/ref/semver_vectors.js, generated by
// tools/gen_semver_ref_vectors.mjs). The inputs enumerate the forms that
// decide precedence and membership -- every prerelease shape against every
// other, every range operator against every version -- rather than sampling
// them.
import * as sv from "dyna:semver";
import { ROWS, VALID, RANGES } from "../corpus/ref/semver_vectors.js";

// rows name versions as "v<i>" (VALID[i]) and ranges as "r<i>" (RANGES[i])
const LISTS = { "@VALID": VALID, "@VALID_REVERSED": VALID.slice().reverse() };
const deref = (a) => {
    if (typeof a !== "string") return a;
    if (a in LISTS) return LISTS[a];
    if (/^v\d+$/.test(a)) return VALID[+a.slice(1)];
    if (/^r\d+$/.test(a)) return RANGES[+a.slice(1)];
    return a;
};

let n = 0, fails = 0;
const shown = new Map();
function fail(op, m) {
    fails++;
    const k = (shown.get(op) || 0) + 1;
    shown.set(op, k);
    if (k <= 8) print("FAIL: " + m);
}
const OPS = {
    isValid: ([v]) => sv.isValid(v),
    parse: ([v]) => { const p = sv.parse(v); return { major: p.major, minor: p.minor, patch: p.patch, prerelease: p.prerelease, build: p.build, version: p.version }; },
    prerelease: ([v]) => sv.prerelease(v),
    compare: ([a, b]) => sv.compare(a, b),
    compareBuild: ([a, b]) => sv.compareBuild(a, b),
    sortProperty: ([vs]) => {
        const out = sv.sort(vs);
        const perm = JSON.stringify(out.slice().sort()) === JSON.stringify(vs.slice().sort());
        let ordered = true;
        for (let i = 1; i < out.length; i++) if (sv.compare(out[i - 1], out[i]) > 0) ordered = false;
        return perm && ordered && out !== vs;
    },
    // one row per range: bit i says whether VALID[i] satisfies it
    satisfiesAll: ([r]) => VALID.map((v) => (sv.satisfies(v, r) ? "1" : "0")).join(""),
    maxSatisfying: ([vs, r]) => sv.maxSatisfying(vs, r),
    minSatisfying: ([vs, r]) => sv.minSatisfying(vs, r),
    // one row per range: bit j says whether it intersects RANGES[j]
    intersectsAll: ([a]) => RANGES.map((b) => (sv.intersects(a, b) ? "1" : "0")).join(""),
    inc: ([v, rel, id]) => (id === null ? sv.inc(v, rel) : sv.inc(v, rel, id)),
    clean: ([v]) => sv.clean(v),
};
const count = new Map();
for (let [op, args, want] of ROWS) {
    n++;
    count.set(op, (count.get(op) || 0) + 1);
    let got;
    args = args.map(deref);
    try { got = OPS[op](args); } catch (e) { fail(op, op + "(" + JSON.stringify(args).slice(1, -1).slice(0, 90) + ") threw " + e.message); continue; }
    if (JSON.stringify(got) !== JSON.stringify(want))
        fail(op, op + "(" + JSON.stringify(args).slice(1, -1).slice(0, 90) + ") = " + JSON.stringify(got) + ", node-semver says " + JSON.stringify(want));
}
for (const [op, k] of shown) if (k > 8) print("  ... " + op + ": " + (k - 8) + " more");
print("test_semver_ref: " + n + " checks (" + [...count].map(([k, v]) => k + " " + v).join(", ") + "), " + fails + " failures");
if (fails) throw new Error(fails + " failures");
